const selectedMode = bru.getEnvVar("MODE");
const modes = ["dev", "stag", "prod"];
if (!modes.includes(selectedMode)) {
  throw new Error("Select the dev, stag or prod environment before sending requests.");
}

const effective = (name) => bru.getEnvVar(name);

function endpointOrigin(endpoint) {
  if (typeof endpoint !== "string" || /\s/.test(endpoint)) {
    throw new Error("Expected an absolute HTTP(S) endpoint without whitespace.");
  }

  const match = /^(https?):\/\/([^\/?#@]+)(\/[^?#]*)?$/.exec(endpoint);
  if (!match) {
    throw new Error("Endpoints must not contain credentials, query parameters or fragments.");
  }

  return match[1] + "://" + match[2];
}

for (const name of ["EPA_AUTHORIZATION_BASE_URL", "OIDC_ISSUER", "OIDC_DEFAULT_REDIRECT_URI"]) {
  const value = effective(name);
  const origin = endpointOrigin(value);
  if (origin.endsWith(".invalid")) {
    throw new Error("Replace the " + selectedMode + " placeholder for " + name + ".");
  }
  if (selectedMode !== "dev" && !value.startsWith("https://")) {
    throw new Error("Stag and prod require HTTPS for " + name + ".");
  }
}

for (const name of ["EPA_AUTHORIZATION_BASE_URL", "OIDC_ISSUER"]) {
  if (effective(name).endsWith("/")) {
    throw new Error(name + " must not end with a slash.");
  }
}

if (!effective("OIDC_CLIENT_ID") || !effective("OIDC_SCOPE")) {
  throw new Error("OIDC_CLIENT_ID and OIDC_SCOPE must be configured.");
}
if (!/^[a-zA-Z0-9-]{1,20}\/[a-zA-Z0-9.-]{1,15}$/.test(effective("X_USERAGENT"))) {
  throw new Error("X_USERAGENT must match product/version, with lengths 20/15 at most.");
}

const context = JSON.stringify([
  selectedMode,
  effective("OIDC_ISSUER"),
  effective("OIDC_CLIENT_ID"),
  effective("OIDC_DEFAULT_REDIRECT_URI"),
  effective("EPA_AUTHORIZATION_BASE_URL"),
]);

// Discard references and endpoints when changing the selected deployment.
if (bru.getVar("LAB_CONTEXT") !== context) {
  for (const name of [
    "DISCOVERY_CONTEXT",
    "IDP_AUTHORIZATION_ENDPOINT",
    "IDP_PAR_ENDPOINT",
    "IDP_JWKS_URI",
    "AUTHORIZATION_CONTEXT",
    "AUTHORIZATION_URL",
    "PAR_EXPIRES_IN",
  ]) {
    bru.deleteVar(name);
  }
}
bru.setVar("LAB_CONTEXT", context);

const requestIdBytes = crypto.getRandomValues(new Uint8Array(16));
requestIdBytes[6] = (requestIdBytes[6] & 15) | 64;
requestIdBytes[8] = (requestIdBytes[8] & 63) | 128;
const requestIdHex = Array.from(requestIdBytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
const requestId = [
  requestIdHex.slice(0, 8),
  requestIdHex.slice(8, 12),
  requestIdHex.slice(12, 16),
  requestIdHex.slice(16, 20),
  requestIdHex.slice(20),
].join("-");
bru.setVar("REQUEST_ID", requestId);

