const responseStatus = res.getStatus();
const responseBody = res.getBody();
const responseHeader = (name) => res.getHeader(name);
function endpointOrigin(endpoint) {
  if (typeof endpoint !== "string" || /\s/.test(endpoint)) {
    throw new Error("Expected an absolute HTTP(S) endpoint without whitespace.");
  }

  const match = /^(https?):\/\/([^\/?#@]+)(\/[^?#]*)?$/.exec(endpoint);
  if (!match) {
    throw new Error("Endpoints must not contain credentials, query parameters or fragments.");
  }

  return match[1] + "://" + match[2];
}

const metadata = typeof responseBody === "string" ? JSON.parse(responseBody) : responseBody;
test("Discovery returns the exact configured issuer and PAR/PKCE capabilities", () => {
  expect(responseStatus).to.equal(200);
  expect(metadata.issuer).to.equal(get("OIDC_ISSUER"));
  expect(metadata.response_types_supported).to.include("code");
  expect(metadata.code_challenge_methods_supported).to.include("S256");
  expect(metadata.token_endpoint_auth_methods_supported).to.include("client_secret_basic");
});

// Persist only validated endpoints from the current issuer.
if (responseStatus !== 200 || metadata.issuer !== get("OIDC_ISSUER")) {
  throw new Error("Discovery did not return the configured issuer.");
}
const issuerOrigin = endpointOrigin(metadata.issuer);
const endpoints = {
  IDP_AUTHORIZATION_ENDPOINT: metadata.authorization_endpoint,
  IDP_PAR_ENDPOINT: metadata.pushed_authorization_request_endpoint,
  IDP_JWKS_URI: metadata.jwks_uri,
};
for (const [name, endpoint] of Object.entries(endpoints)) {
  if (endpointOrigin(endpoint) !== issuerOrigin) {
    throw new Error("Discovered " + name + " must have the same origin as OIDC_ISSUER.");
  }
}
for (const [name, endpoint] of Object.entries(endpoints)) {
  save(name, endpoint);
}
save("DISCOVERY_CONTEXT", get("LAB_CONTEXT"));

