const get = (name) => bru.getVar(name) ?? bru.getEnvVar(name);
const save = (name, value) => bru.setVar(name, value);
const clear = (name) => bru.deleteVar(name);
if (!get("DISCOVERY_CONTEXT") || get("DISCOVERY_CONTEXT") !== get("LAB_CONTEXT")) {
  throw new Error("Run idp / OIDC discovery for the selected environment first.");
}
const clientSecret = bru.getEnvVar("OIDC_CLIENT_SECRET") ||
  bru.getProcessEnv(get("MODE").toUpperCase() + "_OIDC_CLIENT_SECRET");
if (typeof clientSecret !== "string" || clientSecret.length === 0) {
  throw new Error("Set OIDC_CLIENT_SECRET locally in the selected environment for direct IDP PAR.");
}

const btoa = require("btoa");
function base64url(bytes) {
  return btoa(Array.from(bytes, (byte) => String.fromCharCode(byte)).join(""))
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/, "");
}

function formEncode(value) {
  return encodeURIComponent(value)
    .replace(/[!'()~]/g, (character) => "%" + character.charCodeAt(0).toString(16).toUpperCase())
    .replace(/%20/g, "+");
}

const verifier = base64url(crypto.getRandomValues(new Uint8Array(32)));
const CryptoJS = require("crypto-js");
const challenge = CryptoJS.SHA256(verifier).toString(CryptoJS.enc.Base64)
  .replace(/\+/g, "-")
  .replace(/\//g, "_")
  .replace(/=+$/, "");
bru.setVar("PAR_STATE", base64url(crypto.getRandomValues(new Uint8Array(32))));
bru.setVar("PAR_NONCE", base64url(crypto.getRandomValues(new Uint8Array(32))));
bru.setVar("PAR_CODE_CHALLENGE", challenge);

// OAuth client_secret_basic form-encodes both components before Base64.
const credentials = formEncode(get("OIDC_CLIENT_ID")) + ":" + formEncode(clientSecret);
bru.setVar("PAR_BASIC_AUTH", "Basic " + btoa(credentials));
clear("AUTHORIZATION_URL");
clear("AUTHORIZATION_CONTEXT");

