test("IDP accepts a real PAR reference with a positive lifetime", () => {
  expect(responseStatus).to.equal(201);
  expect(pushedRequest.request_uri).to.match(/^urn:ietf:params:oauth:request_uri:.+/);
  expect(pushedRequest.expires_in).to.be.a("number").and.above(0);
});

if (responseStatus === 201 && typeof pushedRequest.request_uri === "string" &&
    pushedRequest.request_uri.startsWith("urn:ietf:params:oauth:request_uri:") &&
    pushedRequest.expires_in > 0) {
  const authorizationUrl = get("IDP_AUTHORIZATION_ENDPOINT") +
    "?client_id=" + encodeURIComponent(get("OIDC_CLIENT_ID")) +
    "&request_uri=" + encodeURIComponent(pushedRequest.request_uri);
  save("AUTHORIZATION_URL", authorizationUrl);
  save("AUTHORIZATION_CONTEXT", get("LAB_CONTEXT"));
  save("PAR_EXPIRES_IN", pushedRequest.expires_in);
}
