const responseStatus = res.getStatus();
const responseBody = res.getBody();
const responseHeader = (name) => res.getHeader(name);
const location = responseHeader("Location");
test("Authorization returns an empty 302 response with only client_id and request_uri", () => {
  expect(responseStatus).to.equal(302);
  expect(responseBody).to.equal("");
  expect(location).to.be.a("string");
  const separator = location.indexOf("?");
  expect(location.slice(0, separator)).to.equal(get("IDP_AUTHORIZATION_ENDPOINT"));
  const parameters = location.slice(separator + 1).split("&").map((parameter) => {
    const equals = parameter.indexOf("=");
    return [
      decodeURIComponent(parameter.slice(0, equals)),
      decodeURIComponent(parameter.slice(equals + 1).replace(/\+/g, " ")),
    ];
  });
  expect(parameters.map(([name]) => name).sort()).to.deep.equal(["client_id", "request_uri"]);
  const query = Object.fromEntries(parameters);
  expect(query.client_id).to.equal(get("OIDC_CLIENT_ID"));
  expect(query.request_uri).to.match(/^urn:ietf:params:oauth:request_uri:.+/);
});

if (responseStatus === 302 && typeof location === "string" &&
    location.startsWith(get("IDP_AUTHORIZATION_ENDPOINT") + "?")) {
  save("AUTHORIZATION_URL", location);
  save("AUTHORIZATION_CONTEXT", get("LAB_CONTEXT"));
}

